// HMAC-SHA1 per RFC 2104, implemented from scratch in pure JS.
// No node:crypto — relies only on the local ./sha1.mjs implementation.

import { sha1 } from './sha1.mjs';

const BLOCK_SIZE = 64; // SHA-1 block size in bytes

/**
 * Compute HMAC-SHA1 (RFC 2104).
 * @param {Uint8Array} key
 * @param {Uint8Array} message
 * @returns {Uint8Array} 20-byte tag
 */
export function hmacSha1(key, message) {
  let k = key;
  if (k.length > BLOCK_SIZE) {
    k = sha1(k);
  }

  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(k); // shorter keys are zero-padded to 64 bytes

  const oKeyPad = new Uint8Array(BLOCK_SIZE);
  const iKeyPad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    oKeyPad[i] = paddedKey[i] ^ 0x5c;
    iKeyPad[i] = paddedKey[i] ^ 0x36;
  }

  // inner = sha1(iKeyPad || message)
  const inner = new Uint8Array(BLOCK_SIZE + message.length);
  inner.set(iKeyPad);
  inner.set(message, BLOCK_SIZE);
  const innerHash = sha1(inner);

  // tag = sha1(oKeyPad || innerHash)
  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(oKeyPad);
  outer.set(innerHash, BLOCK_SIZE);
  return sha1(outer);
}

