// PBKDF2 (RFC 2898 / PKCS#5) with PRF = HMAC-SHA1.
// Pure JavaScript, no external dependencies.

import { hmacSha1 } from './hmac.mjs';

// SHA-1 produces 20-byte digests, so each PBKDF2 block is 20 bytes.
const H_LEN = 20;

/**
 * Derives a key using PBKDF2 with HMAC-SHA1 as the PRF.
 *
 * @param {Uint8Array} password - The password, as bytes.
 * @param {Uint8Array} salt - The salt, as bytes.
 * @param {number} iterations - Iteration count (c), a positive integer.
 * @param {number} dkLen - Desired derived key length in bytes.
 * @returns {Uint8Array} The derived key, exactly dkLen bytes long.
 */
export function pbkdf2Sha1(password, salt, iterations, dkLen) {
  if (!Number.isInteger(iterations) || iterations < 1) {
    throw new RangeError('iterations must be a positive integer');
  }
  if (!Number.isInteger(dkLen) || dkLen < 0) {
    throw new RangeError('dkLen must be a non-negative integer');
  }

  const blockCount = Math.ceil(dkLen / H_LEN);
  // RFC 2898: dkLen must not exceed (2^32 - 1) * hLen.
  if (blockCount > 0xffffffff) {
    throw new RangeError('derived key too long');
  }

  const derivedKey = new Uint8Array(blockCount * H_LEN);

  // salt || INT_32_BE(i), reused for every block.
  const blockInput = new Uint8Array(salt.length + 4);
  blockInput.set(salt, 0);

  for (let i = 1; i <= blockCount; i++) {
    // INT_32_BE(i): encode block index as 4-byte big-endian.
    blockInput[salt.length] = (i >>> 24) & 0xff;
    blockInput[salt.length + 1] = (i >>> 16) & 0xff;
    blockInput[salt.length + 2] = (i >>> 8) & 0xff;
    blockInput[salt.length + 3] = i & 0xff;

    // U1 = PRF(password, salt || INT_32_BE(i))
    let u = hmacSha1(password, blockInput);
    const t = new Uint8Array(u);

    // Uj = PRF(password, U(j-1)); T = U1 xor U2 ... xor Uc
    for (let j = 2; j <= iterations; j++) {
      u = hmacSha1(password, u);
      for (let k = 0; k < H_LEN; k++) {
        t[k] ^= u[k];
      }
    }

    derivedKey.set(t, (i - 1) * H_LEN);
  }

  return derivedKey.subarray(0, dkLen);
}

