// Manual argparse-style CLI parsing for test2.mjs.
// Mirrors the Python argparse behavior of the original test2_executable:
//   usage: test2_executable [-h] --a A --b B --c C
// --a: passphrase (string), --b: salt (string), --c: iterations (int).

const PROG = 'test2_executable';
const USAGE = `usage: ${PROG} [-h] --a A --b B --c C`;

const HELP = `${USAGE}

options:
  -h, --help  show this help message and exit
  --a A       passphrase
  --b B       salt
  --c C       iterations
`;

// Order in which missing required options are reported.
const REQUIRED = ['--a', '--b', '--c'];
const KNOWN = new Set(REQUIRED);

function fail(message) {
  process.stderr.write(USAGE + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

// Python int() semantics for a base-10 string: surrounding whitespace
// tolerated, optional leading '+' or '-', then ASCII digits only.
function parsePythonInt(raw) {
  const s = raw.trim();
  if (!/^[+-]?\d+$/.test(s)) return null;
  return parseInt(s, 10);
}

export function parseArgs(argv) {
  const values = { '--a': null, '--b': null, '--c': null };
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      process.stdout.write(HELP);
      process.exit(0);
    }

    // Split "--x=value" into option and inline value; otherwise the value
    // is the next token ("--x value" form).
    let opt = token;
    let inlineValue = null;
    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      opt = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    if (!KNOWN.has(opt)) {
      extras.push(token);
      continue;
    }

    let value;
    if (inlineValue !== null) {
      value = inlineValue;
    } else if (i + 1 < argv.length) {
      value = argv[++i];
    } else {
      fail(`argument ${opt}: expected one argument`);
    }

    if (opt === '--c') {
      const n = parsePythonInt(value);
      if (n === null) {
        fail(`argument --c: invalid int value: '${value}'`);
      }
      values['--c'] = n;
    } else {
      values[opt] = value;
    }
  }

  const missing = REQUIRED.filter((opt) => values[opt] === null);
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values['--a'], b: values['--b'], c: values['--c'] };
}

