// Entry point: PBKDF2-HMAC-SHA1 CLI, mirroring the original Python script.
//   node test2.mjs --a <passphrase> --b <salt> --c <iterations>
// Prints the 20-byte derived key as a lowercase hex string (like Python's
// result.hex() + print).

import { parseArgs } from './args.mjs';
import { pbkdf2Sha1 } from './pbkdf2.mjs';

const { a, b, c } = parseArgs(process.argv.slice(2));

const encoder = new TextEncoder();
const passwordBytes = encoder.encode(a);
const saltBytes = encoder.encode(b);

const derived = pbkdf2Sha1(passwordBytes, saltBytes, c, 20);

let hex = '';
for (const byte of derived) {
  hex += byte.toString(16).padStart(2, '0');
}
console.log(hex);

