// Pure-JS SHA-1 (FIPS 180-1) for Node.js ESM. No external dependencies.

const K = [0x5a827999, 0x6ed9eba1, 0x8f1bbcdc, 0xca62c1d6];

function rotl(x, n) {
  return ((x << n) | (x >>> (32 - n))) >>> 0;
}

export function sha1(data) {
  const msgLen = data.length;
  const bitLen = msgLen * 8;

  // MD strengthening: append 0x80, pad with zeros until 56 mod 64,
  // then append the 64-bit big-endian message length in bits.
  const paddedLen = (msgLen + 9 + 63) & ~63; // smallest multiple of 64 >= msgLen + 9
  const buf = new Uint8Array(paddedLen);
  buf.set(data);
  buf[msgLen] = 0x80;
  // Big-endian 64-bit bit length. JS bit ops are 32-bit, so split.
  // bitLen may exceed 2^32 only for huge inputs; use safe-integer math.
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  const v = new DataView(buf.buffer);
  v.setUint32(paddedLen - 8, hi);
  v.setUint32(paddedLen - 4, lo);

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const w = new Uint32Array(80);

  for (let off = 0; off < paddedLen; off += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = v.getUint32(off + t * 4);
    }
    for (let t = 16; t < 80; t++) {
      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
    }

    let a = h0, b = h1, c = h2, d = h3, e = h4;

    for (let t = 0; t < 80; t++) {
      let f, k;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = K[0];
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = K[1];
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = K[2];
      } else {
        f = b ^ c ^ d;
        k = K[3];
      }
      const tmp = (rotl(a, 5) + f + e + k + w[t]) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = tmp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  const out = new Uint8Array(20);
  const ov = new DataView(out.buffer);
  ov.setUint32(0, h0);
  ov.setUint32(4, h1);
  ov.setUint32(8, h2);
  ov.setUint32(12, h3);
  ov.setUint32(16, h4);
  return out;
}

