9	export function sha1(data) {
10	  const msgLen = data.length;
11	  const bitLen = msgLen * 8;
12	
13	  // MD strengthening: append 0x80, pad with zeros until 56 mod 64,
14	  // then append the 64-bit big-endian message length in bits.
15	  const paddedLen = (msgLen + 9 + 63) & ~63; // smallest multiple of 64 >= msgLen + 9
16	  const buf = new Uint8Array(paddedLen);
17	  buf.set(data);
18	  buf[msgLen] = 0x80;
19	  // Big-endian 64-bit bit length. JS bit ops are 32-bit, so split.
20	  // bitLen may exceed 2^32 only for huge inputs; use safe-integer math.
21	  const hi = Math.floor(bitLen / 0x100000000);
22	  const lo = bitLen >>> 0;
23	  const v = new DataView(buf.buffer);
24	  v.setUint32(paddedLen - 8, hi);
25	  v.setUint32(paddedLen - 4, lo);
26	
