28	  let h1 = 0xefcdab89;
29	  let h2 = 0x98badcfe;
30	  let h3 = 0x10325476;
31	  let h4 = 0xc3d2e1f0;
32	
33	  const w = new Uint32Array(80);
34	
35	  for (let off = 0; off < paddedLen; off += 64) {
36	    for (let t = 0; t < 16; t++) {
37	      w[t] = v.getUint32(off + t * 4);
38	    }
39	    for (let t = 16; t < 80; t++) {
40	      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
41	    }
